import{_ as p,a0 as d,w as r,s as o,ao as l,I as t,x as s,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何在 Linux 上安装 Java | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上安装 Java | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上安装 Java | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上安装 Java | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191120 How to install Java on Linux","title":"如何在 Linux 上安装 Java","tag":"201911","desc":""},"relativePath":"201911/20191120 How to install Java on Linux.md","filePath":"[post].md"}'),h={name:"201911/20191120 How to install Java on Linux.md"};function u(c,a,k,b,g,v){const e=d("Link");return r(),o("div",null,[a[23]||(a[23]=l('<h1 id="如何在-linux-上安装-java" tabindex="-1">如何在 Linux 上安装 Java <a class="header-anchor" href="#如何在-linux-上安装-java" aria-label="Permalink to “如何在 Linux 上安装 Java”">​</a></h1><blockquote><p>在桌面上拥抱 Java 应用程序，然后在所有桌面上运行它们。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/26/065307hk22caubakkos0u0.jpg" alt=""></p><p>无论你运行的是哪种操作系统，通常都有几种安装应用程序的方法。有时你可能会在应用程序商店中找到一个应用程序，或者使用 Fedora 上的 DNF 或 Mac 上的 Brew 这样的软件包管理器进行安装，而有时你可能会从网站上下载可执行文件或安装程序。因为 Java 是这么多流行的应用程序的后端，所以最好了解安装它的不同方法。好消息是你有很多选择，本文涵盖了所有这些内容。</p><p>坏消息是 Java <em>太大</em>，我说的不仅仅是文件大小。Java 是一种开放源代码语言和规范，这意味着从理论上讲，任何人都可以创建它的实现版本。这意味着，在安装任何东西之前，必须确定要安装的 Java 发行版。</p><h3 id="我需要-jvm-还是-jre-或者-jdk" tabindex="-1">我需要 JVM 还是 JRE 或者 JDK？ <a class="header-anchor" href="#我需要-jvm-还是-jre-或者-jdk" aria-label="Permalink to “我需要 JVM 还是 JRE 或者 JDK？”">​</a></h3><p>Java 大致分为两个下载类别。<ruby>Java 虚拟机<rt>Java Virtual Machine</rt></ruby>（JVM）是运行时组件；它是使 Java 应用程序能够在计算机上启动和运行的“引擎”。它包含在 <ruby>Java 运行时环境<rt>Java Runtime Environment</rt></ruby>（JRE）中。</p><p><ruby>Java 开发工具包<rt>Java Development Kit</rt></ruby>（JDK）是一个开发工具包：你可以将其视为一个车库，修理工可以坐在那里进行调整、修理和改进。JDK 包含 Java 运行时环境（JRE）。</p><p>以下载来说，这意味着：</p><ul><li>如果你是希望运行 Java 应用程序的用户，则只需 JRE（包括了 JVM）。</li><li>如果你是希望使用 Java 进行编程的开发人员，则需要 JDK（包括 JRE 库，而 JRE 库又包括 JVM）。</li></ul><h3 id="openjdk、icedtea-和-oraclejdk-有什么不同" tabindex="-1">OpenJDK、IcedTea 和 OracleJDK 有什么不同？ <a class="header-anchor" href="#openjdk、icedtea-和-oraclejdk-有什么不同" aria-label="Permalink to “OpenJDK、IcedTea 和 OracleJDK 有什么不同？”">​</a></h3><p>当<ruby>太阳微系统<rt>Sun Microsystems</rt></ruby>被 Oracle 收购时，Java 是该交易的主要部分。幸运的是，Java 是一种开源技术，因此，如果你对 Oracle 维护该项目的方式不满意，则可以选择其他方法。Oracle 将专有组件与 Java 下载捆绑在一起，而 OpenJDK 项目是完全开源的。</p><p>IcedTea 项目本质上是 OpenJDK，但其目标是使用户在使用完全自由开源的工具时更容易构建和部署 OpenJDK。</p><p>（LCTT 译注：阿里巴巴也有一个它自己维护的 Open JDK 发行版“<ruby>龙井<rt>Dragonwell</rt></ruby>”。以下引自其官网：“Alibaba Dragonwell 是一款免费的，生产就绪型 Open JDK 发行版，提供长期支持，包括性能增强和安全修复。……Alibaba Dragonwell 作为 Java 应用的基石，支撑了阿里经济体内所有的 Java 业务。Alibaba Dragonwell 完全兼容 Java SE 标准，……”）</p><h3 id="我应该安装哪个-java" tabindex="-1">我应该安装哪个 Java？ <a class="header-anchor" href="#我应该安装哪个-java" aria-label="Permalink to “我应该安装哪个 Java？”">​</a></h3><p>如果你对这些选择感到不知所措，那么简单的答案就是你应该安装的 Java 实现应该是最容易安装的那个。当应用程序告诉你需要 Java 12，但你的存储库中只有 Java 8 时，可以安装可以从可靠来源中找到的 Java 12 的任何实现。在 Linux 上，你可以一次安装几个不同版本的 Java，它们不会互相干扰。</p>',16)),t("p",null,[a[1]||(a[1]=s("如果你是需要选择使用哪个版本的开发人员，则应考虑所需的组件。如果选择 Oracle 的版本，请注意，软件包中包含专有的插件和字体，可能会",-1)),i(e,{href:"https://www.oracle.com/technetwork/java/javase/overview/oracle-jdk-faqs.html"},{default:n(()=>[...a[0]||(a[0]=[s("影响你分发你的应用程序",-1)])]),_:1}),a[2]||(a[2]=s("。在 IcedTea 或 OpenJDK 上进行开发是最安全的。",-1))]),a[24]||(a[24]=l(`<h3 id="从存储库安装-openjdk" tabindex="-1">从存储库安装 OpenJDK？ <a class="header-anchor" href="#从存储库安装-openjdk" aria-label="Permalink to “从存储库安装 OpenJDK？”">​</a></h3><p>现在，你已经知道要选择什么了，你可以使用软件包管理器搜索 OpenJDK 或 IcedTea，然后安装所需的版本。有些发行版使用关键字 <code>latest</code> 来指示最新版本，这通常是你要运行的应用程序所需要的。根据你使用的软件包管理器，你甚至可以考虑使用 <code>grep</code> 过滤搜索结果以仅包括最新版本。例如，在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf search openjdk | grep latest | cut -f1 -d&#39;:&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>java-latest-openjdk-demo.x86_64</span></span>
<span class="line"><span>java-openjdk.i686</span></span>
<span class="line"><span>java-openjdk.x86_64</span></span>
<span class="line"><span>java-latest-openjdk-jmods.x86_64</span></span>
<span class="line"><span>java-latest-openjdk-src.x86_64</span></span>
<span class="line"><span>java-latest-openjdk.x86_64</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>只有当你尝试运行的应用程序坚持要求你使用 Java 的旧版本时，你才应该看看 <code>latest</code> 之前的版本。</p><p>在 Fedora 或类似系统上安装 Java：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install java-latest-openjdk</span></span></code></pre></div><p>如果你的发行版不使用 <code>latest</code> 标签，则可以使用其他关键字，例如 <code>default</code>。以下是在 Debian 上搜索 OpenJDK 的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt search openjdk | less</span></span>
<span class="line"><span>default-jdk</span></span>
<span class="line"><span>  Standard Java development kit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default-jre</span></span>
<span class="line"><span>  Standard Java runtime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>openjdk-11-jdk</span></span>
<span class="line"><span>  OpenJDK development kit (JDK)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在这种情况下，<code>default-jre</code> 软件包适合用户，而 <code>default-jdk</code> 则适合开发人员。</p><p>例如，要在 Debian 上安装 JRE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install default-jre</span></span></code></pre></div><p>现在已安装好 Java。</p><p>你的存储库中可能有<em>许多</em>与 Java 相关的软件包。要搜索 OpenJDK，如果你是用户，则查找最新的 JRE 或 JVM，如果你是开发人员，则查找最新的 JDK。</p><h3 id="从互联网上安装-java" tabindex="-1">从互联网上安装 Java <a class="header-anchor" href="#从互联网上安装-java" aria-label="Permalink to “从互联网上安装 Java”">​</a></h3>`,14)),t("p",null,[a[5]||(a[5]=s("如果在存储库中找不到 JRE 或 JDK，或者找不到满足你需求的 JRE 或 JDK，则可以从互联网上下载开源的 Java 软件包。你可以在 ",-1)),i(e,{href:"http://openjdk.java.net"},{default:n(()=>[...a[3]||(a[3]=[s("openjdk.java.net",-1)])]),_:1}),a[6]||(a[6]=s(" 中找到需要手动安装的 tar 形式的 OpenJDK 下载文件，或者可以从 Azul 下载 tar 形式的 ",-1)),i(e,{href:"https://www.azul.com/downloads/zulu-community"},{default:n(()=>[...a[4]||(a[4]=[s("Zulu 社区版",-1)])]),_:1}),a[7]||(a[7]=s("或其可安装的 RPM 或 DEB 软件包。",-1))]),a[25]||(a[25]=l(`<h4 id="从-tar-文件安装-java" tabindex="-1">从 TAR 文件安装 Java <a class="header-anchor" href="#从-tar-文件安装-java" aria-label="Permalink to “从 TAR 文件安装 Java”">​</a></h4><p>如果从 Java.net 或 Azul 下载 TAR 文件，则必须手动安装。这通常称为“本地”安装，因为你没有将 Java 安装到“全局”位置。你可以在 <code>PATH</code> 中选择一个合适的位置。</p><p>如果你不知道 <code>PATH</code> 中包含什么，请查看一下以找出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/home/seth/bin</span></span></code></pre></div><p>在此示例 <code>PATH</code> 中，位置 <code>/usr/local/bin</code> 和 <code>/home/seth/bin</code> 是不错的选择。如果你是计算机上的唯一用户，那么你自己的家目录就很有意义。如果你的计算机上有很多用户，则最好选择一个通用位置，例如 <code>/usr/local</code> 或 <code>/opt</code>。</p><p>如果你无权访问需要 <code>sudo</code> 权限的 <code>/usr/local</code> 之类的系统级目录，则可以在你自己的家目录中创建一个本地 <code>bin</code>（意思是 “<ruby>二进制<rt>binary</rt></ruby>”，而不是“<ruby>垃圾箱<rt>waste bin</rt></ruby>”）或 <code>Applications</code> 文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/bin</span></span></code></pre></div><p>如果它不在你的 <code>PATH</code> 中，请将其添加到其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo PATH=$PATH:$HOME/bin &amp;gt;&amp;gt; ~/.bashrc</span></span>
<span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>最后，将压缩包解压缩到你选择的目录中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file openjdk*linux-x64_bin.tar.gz --directory=$HOME/bin</span></span></code></pre></div><p>Java 现在安装好了。</p><h4 id="从-rpm-或-deb-安装-java" tabindex="-1">从 RPM 或 DEB 安装 Java <a class="header-anchor" href="#从-rpm-或-deb-安装-java" aria-label="Permalink to “从 RPM 或 DEB 安装 Java”">​</a></h4><p>如果从 Azul.com 下载 RPM 或 DEB 文件，则可以使用软件包管理器进行安装。</p><p>对于 Fedora、CentOS、RHEL 等，请下载 RPM 并使用 DNF 进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install zulu*linux.x86_64.rpm</span></span></code></pre></div><p>对于 Debian、Ubuntu、Pop_OS 和类似发行版，请下载 DEB 软件包并使用 Apt 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i zulu*linux_amd64.deb</span></span></code></pre></div><p>Java 现在安装好了。</p><h4 id="用-alternatives-安装你的-java-版本" tabindex="-1">用 alternatives 安装你的 Java 版本 <a class="header-anchor" href="#用-alternatives-安装你的-java-版本" aria-label="Permalink to “用 alternatives 安装你的 Java 版本”">​</a></h4><p>一些应用程序是为特定版本的 Java 开发的，不能与其他任何版本一起使用。这种情况很少见，但确实会发生，在 Linux 上，你可以使用本地安装方法（请参阅上面“从 TAR 文件安装 Java”一节）或使用 <code>alternatives</code> 应用程序来解决此冲突。</p><p><code>alternatives</code> 命令会查找 Linux 系统上安装的应用程序，并让你选择要使用的版本。有些发行版，例如 Slackware，不提供 <code>alternatives</code> 命令，因此你必须使用本地安装方法。在 Fedora、CentOS 和类似的发行版上，该命令是 <code>alternatives</code>。在 Debian、Ubuntu 和类似的系统上，该命令是 <code>update-alternatives</code>。</p><p>要获取当前已安装在 Fedora 系统上的应用程序的可用版本列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alternatives --list</span></span></code></pre></div><p>在 Debian 上，你必须指定可供替代的应用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ update-alternatives --list java</span></span></code></pre></div><p>在 Fedora 上选择要使系统将哪个版本作为默认版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo alternatives --config java</span></span></code></pre></div><p>在 Debian 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo updates-alternatives --config java</span></span></code></pre></div><p>你可以根据需要运行的应用程序，根据需要更改默认的 Java 版本。</p><h3 id="运行-java-应用" tabindex="-1">运行 Java 应用 <a class="header-anchor" href="#运行-java-应用" aria-label="Permalink to “运行 Java 应用”">​</a></h3><p>Java 应用程序通常以 JAR 文件的形式分发。根据你安装 Java 的方式，你的系统可能已经为运行 Java 应用程序配置好了，这使你只需双击应用程序图标（或从应用程序菜单中选择它）即可运行。如果必须执行未与系统其余部分集成的本地 Java 安装，则可以直接从终端启动 Java 应用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -jar ~/bin/example.jar &amp;</span></span></code></pre></div><h3 id="java-是个好东西" tabindex="-1">Java 是个好东西 <a class="header-anchor" href="#java-是个好东西" aria-label="Permalink to “Java 是个好东西”">​</a></h3><p>Java 是少数将跨平台开发放在首位的编程环境之一。没有什么比问一个应用程序是否能在你的平台上运行然后发现该应用程序是用 Java 编写要让人感到松一口气的了。它是如此简单，无论你是开发人员还是用户，你都可以摆脱任何平台上的焦虑。在桌面上拥抱 Java 应用程序，然后在<em>所有</em>桌面上运行它们吧。</p><hr>`,37)),t("p",null,[a[9]||(a[9]=s("via: ",-1)),i(e,{href:"https://opensource.com/article/19/11/install-java-linux"},{default:n(()=>[...a[8]||(a[8]=[s("https://opensource.com/article/19/11/install-java-linux",-1)])]),_:1})]),t("p",null,[a[14]||(a[14]=s("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[10]||(a[10]=[s("Seth Kenlon",-1)])]),_:1}),a[15]||(a[15]=s(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[12]||(a[12]=[s("wxy",-1)])]),_:1}),a[17]||(a[17]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[20]||(a[20]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...a[19]||(a[19]=[s("Linux中国",-1)])]),_:1}),a[22]||(a[22]=s(" 荣誉推出",-1))])])}const j=p(h,[["render",u]]);export{m as __pageData,j as default};
